//! Container menus over plain containers, block entities and the player's ender chest: replays
//! `fixtures/container_menu_golden.txt` (generated by `fixtures/ContainerMenuGolden.java` through the real vanilla menu
//! classes) and compares every state dump: chest rows 1..6 (single and double), hopper, dispenser, shulker box, and a
//! chest, a barrel, a double chest of two chests, a dropper and the ender chest.

use crate::click_support::{Sync, input, mk, st};
use mc_core::ident::Identifier;
use mc_core::pos::{BlockPos, ChunkPos};
use mc_data::block::Block;
use mc_game::server::level::ServerLevel;
use mc_game::world::container::{Container, SimpleContainer};
use mc_game::world::entity::equipment::EquipmentSlot;
use mc_game::world::entity::player::inventory::Inventory;
use mc_game::world::inventory::*;
use mc_game::world::item::ItemStack;
use mc_game::world::level::LevelAccessor;
use mc_game::world::level::flags::{UPDATE_LIMIT, UPDATE_SKIP_ALL_SIDEEFFECTS};
use std::cell::RefCell;
use std::rc::Rc;
use std::time::{Duration, Instant};

struct TestPlayer {
    inv: Inventory,
    creative: bool,
    events: Vec<String>,
    /// `level.getRandom()` of the Java fake level (`RandomSource.create(42 + scenario)`).
    rng: mc_core::random::LegacyRandomSource,
    /// The level holding the block entities of the block-entity scenarios.
    level: Option<ServerLevel>,
    /// `Player.getEnderChestInventory()`.
    ender: PlayerEnderChestContainer,
    /// Whether the scenario's container is a block entity: the dumps then carry a `DIRTY` line.
    be_backed: bool,
    /// Whether it is a barrel, whose closing is a block change.
    barrel: bool,
}

impl TestPlayer {
    /// Whether `setChanged` marked the chunk unsaved since the last call (`FakeLevel.blockEntityChanged`).
    fn take_dirty(&mut self) -> bool {
        self.level
            .as_mut()
            .and_then(|l| l.chunk_now_mut(0, 0))
            .is_some_and(|c| c.data.access.try_mark_saved())
    }
}

impl MenuPlayer for TestPlayer {
    fn registries(&self) -> mc_game::registry::RegistryAccess {
        mc_game::registry::RegistryAccess::empty()
    }
    fn level(&mut self) -> Option<&mut ServerLevel> {
        self.level.as_mut()
    }
    fn level_ref(&self) -> Option<&ServerLevel> {
        self.level.as_ref()
    }
    fn ender_chest(&self) -> Option<&PlayerEnderChestContainer> {
        Some(&self.ender)
    }
    fn ender_chest_mut(&mut self) -> Option<&mut PlayerEnderChestContainer> {
        Some(&mut self.ender)
    }
    fn entity_id(&self) -> i32 {
        0
    }
    fn inventory(&self) -> &Inventory {
        &self.inv
    }
    fn inventory_mut(&mut self) -> &mut Inventory {
        &mut self.inv
    }
    fn has_infinite_materials(&self) -> bool {
        self.creative
    }
    fn is_creative(&self) -> bool {
        self.creative
    }
    fn is_spectator(&self) -> bool {
        false
    }
    fn drop(&mut self, stack: ItemStack, thrown: bool, prediction: Prediction) {
        let p = if prediction == Prediction::Predicted {
            "PREDICTED"
        } else {
            "SERVER_ONLY"
        };
        self.events
            .push(format!("DROP {} {thrown} {p}", st(&stack)));
    }
    fn on_equip_item(&mut self, slot: EquipmentSlot, old: &ItemStack, new: &ItemStack) {
        self.events
            .push(format!("EQUIP {} {} {}", slot.get_name(), st(old), st(new)));
    }
    fn is_within_block_interaction_range(
        &self,
        _pos: mc_core::pos::BlockPos,
        _buffer: f64,
    ) -> bool {
        false
    }
    fn play_player_sound(&mut self, sound: mc_data::SoundEvent, volume: f32, pitch: f32) {
        self.events.push(format!(
            "SOUND {} {} {}",
            sound.name().trim_start_matches("minecraft:"),
            volume.to_bits() as i32,
            pitch.to_bits() as i32
        ));
    }
    fn level_random_next_float(&mut self) -> f32 {
        use mc_core::random::RandomSource;
        self.rng.next_float()
    }
    fn send_inventory_slot_update(&mut self, slot: usize, stack: ItemStack) {
        self.events
            .push(format!("PKT set_player_inventory {slot} {}", st(&stack)));
    }
}

fn dump(
    menu: &mut dyn AbstractContainerMenu,
    p: &mut TestPlayer,
    sync: &Rc<RefCell<Vec<String>>>,
) -> Vec<String> {
    let mut out = vec![format!("C {}", st(menu.base().get_carried()))];
    let mut s = String::from("S");
    for i in 0..menu.base().slots.len() {
        let it = menu.base_mut().with_slot(p, i, |sl, e| sl.get_item(e));
        if !it.is_empty() {
            s += &format!(" {i}:{}", st(&it));
        }
    }
    out.push(s);
    let mut s = String::from("I");
    for i in 0..p.inv.get_container_size() {
        let it = p.inv.get_item(i);
        if !it.is_empty() {
            s += &format!(" {i}:{}", st(it));
        }
    }
    out.push(s);
    out.push(format!("SEL {}", p.inv.get_selected_slot()));
    if p.be_backed {
        let dirty = p.take_dirty();
        out.push(format!("DIRTY {}", u8::from(dirty)));
    }
    out.append(&mut p.events);
    out.append(&mut sync.borrow_mut());
    out
}

/// A detached level whose chunk (0, 0) is loaded: the block entities of the scenario live in it.
fn loaded_level() -> ServerLevel {
    let mut level = ServerLevel::detached(Identifier::parse("minecraft:overworld").unwrap());
    level
        .chunk_source_mut()
        .update_chunk_forced(ChunkPos::new(0, 0), true);
    let start = Instant::now();
    loop {
        level.tick_chunk_source(&|| true, false, true);
        while level.poll_chunk_task() {}
        level.tick_entity_management();
        if level.is_position_ticking_with_entities_loaded(ChunkPos::pack_xz(0, 0)) {
            return level;
        }
        assert!(
            start.elapsed() < Duration::from_secs(120),
            "chunk did not reach entity ticking"
        );
        std::thread::sleep(Duration::from_millis(1));
    }
}

/// The containers a scenario's menu shows, in slot order, with their sizes.
type Parts = Vec<(ContainerKey, usize)>;

/// A scenario's menu; `parts` is what the `cont` ops and the final `CONT` line address.
fn build(kind: i64, p: &mut TestPlayer, parts: &mut Parts) -> Box<dyn AbstractContainerMenu> {
    let shared = |parts: &mut Parts, n: usize| {
        let key = ContainerKey::Shared(Rc::new(RefCell::new(SimpleContainer::new(n))));
        parts.push((key.clone(), n));
        ContainerRef::single(key, n)
    };
    let block_entity = |p: &mut TestPlayer, parts: &mut Parts, block: Block, x: i32, n: usize| {
        let pos = BlockPos::new(x, 64, 0);
        let level = p.level.as_mut().expect("level of a block entity scenario");
        level.set_block(
            pos,
            block.default_state(),
            UPDATE_SKIP_ALL_SIDEEFFECTS,
            UPDATE_LIMIT,
        );
        parts.push((ContainerKey::BlockEntity(pos), n));
        ContainerRef::block_entity(pos, n)
    };
    match kind {
        0 => Box::new(ChestMenu::three_rows(3, p, shared(parts, 27))),
        1 => {
            let (a, b) = (shared(parts, 27), shared(parts, 27));
            Box::new(ChestMenu::six_rows(3, p, ContainerRef::compound([a, b])))
        }
        2 => Box::new(HopperMenu::new(3, p, shared(parts, 5))),
        3 => Box::new(DispenserMenu::new(3, p, shared(parts, 9))),
        4 => Box::new(ShulkerBoxMenu::new(3, p, shared(parts, 27))),
        5 => Box::new(ChestMenu::one_row(3, p, shared(parts, 9))),
        6 => Box::new(ChestMenu::two_rows(3, p, shared(parts, 18))),
        7 => Box::new(ChestMenu::four_rows(3, p, shared(parts, 36))),
        8 => Box::new(ChestMenu::five_rows(3, p, shared(parts, 45))),
        9 => {
            let chest = block_entity(p, parts, Block::CHEST, 0, 27);
            Box::new(ChestMenu::three_rows(3, p, chest))
        }
        10 => {
            let barrel = block_entity(p, parts, Block::BARREL, 0, 27);
            Box::new(ChestMenu::three_rows(3, p, barrel))
        }
        11 => {
            parts.push((ContainerKey::PlayerEnderChest, 27));
            Box::new(ChestMenu::three_rows(
                3,
                p,
                ContainerRef::player_ender_chest(),
            ))
        }
        12 => {
            let dropper = block_entity(p, parts, Block::DROPPER, 0, 9);
            Box::new(DispenserMenu::new(3, p, dropper))
        }
        _ => {
            let a = block_entity(p, parts, Block::CHEST, 0, 27);
            let b = block_entity(p, parts, Block::CHEST, 1, 27);
            Box::new(ChestMenu::six_rows(3, p, ContainerRef::compound([a, b])))
        }
    }
}

/// The `inv`/`cont` ops set the scene before `sync`; after it the script's closing broadcast and dump follow them.
fn close_scene_op(
    player: &mut Option<TestPlayer>,
    menu: &mut Option<Box<dyn AbstractContainerMenu>>,
    sync: &Rc<RefCell<Vec<String>>>,
    actual: &mut Vec<String>,
) {
    let (p, m) = (player.as_mut().unwrap(), menu.as_mut().unwrap());
    if m.base().has_synchronizer() {
        m.broadcast_changes(p);
        *actual = dump(m.as_mut(), p, sync);
    }
}

#[test]
fn container_menu_click_golden() {
    let text = mc_testkit::read_gz(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/container_menu_golden.txt.gz"
    ));
    let sync = Rc::new(RefCell::new(Vec::new()));
    let mut player: Option<TestPlayer> = None;
    let mut menu: Option<Box<dyn AbstractContainerMenu>> = None;
    let mut parts: Parts = Vec::new();
    let mut expected: Vec<&str> = Vec::new();
    let mut actual: Vec<String> = Vec::new();
    let mut op_line = String::new();
    let mut ops = 0;
    let mut history: Vec<String> = Vec::new();

    let finish =
        |op: &str, actual: &mut Vec<String>, expected: &mut Vec<&str>, history: &[String]| {
            for i in 0..actual.len().max(expected.len()) {
                assert_eq!(
                    actual.get(i).map(String::as_str),
                    expected.get(i).copied(),
                    "after op `{op}`, line {i}; recent ops {history:?} actual={actual:?}"
                );
            }
            actual.clear();
            expected.clear();
        };

    for line in text.lines() {
        if let Some(out) = line.strip_prefix("OUT ") {
            if let Some(rest) = out.strip_prefix("CONT") {
                let p = player.as_mut().unwrap();
                let mut s = String::from("CONT");
                let mut idx = 0;
                for (key, size) in &parts {
                    for i in 0..*size {
                        let item = with_player_container(p, key, |c| c.get_item(i).clone());
                        if !item.is_empty() {
                            s += &format!(" {}:{}", idx + i, st(&item));
                        }
                    }
                    idx += size;
                }
                assert_eq!(s, format!("CONT{rest}"), "final container contents");
                continue;
            }
            expected.push(out);
            continue;
        }
        let op = line.strip_prefix("OP ").expect("op line");
        if !op_line.is_empty() {
            finish(
                &op_line,
                &mut actual,
                &mut expected,
                &history[..history.len().saturating_sub(1)],
            );
        }
        op_line = op.to_string();
        ops += 1;
        history.push(op_line.clone());
        if history.len() > 6 {
            history.remove(0);
        }
        let parts_: Vec<&str> = op.split(' ').collect();
        match parts_[0] {
            "scenario" => {
                let scenario: i64 = parts_[1].parse().unwrap();
                let kind: i64 = parts_[2].parse().unwrap();
                let creative = parts_[3] == "creative=true";
                sync.borrow_mut().clear();
                parts.clear();
                let be_backed = matches!(kind, 9 | 10 | 12 | 13);
                let mut p = TestPlayer {
                    inv: Inventory::new(),
                    creative,
                    events: Vec::new(),
                    rng: mc_core::random::LegacyRandomSource::new(42 + scenario),
                    level: be_backed.then(loaded_level),
                    ender: PlayerEnderChestContainer::new(),
                    be_backed,
                    barrel: kind == 10,
                };
                menu = Some(build(kind, &mut p, &mut parts));
                player = Some(p);
            }
            "inv" => {
                let slot: usize = parts_[1].parse().unwrap();
                player.as_mut().unwrap().inv.set_item(
                    slot,
                    mk(
                        parts_[2],
                        parts_[3].parse().unwrap(),
                        parts_[4].parse().unwrap(),
                        parts_[5],
                    ),
                );
                close_scene_op(&mut player, &mut menu, &sync, &mut actual);
            }
            "cont" => {
                let p = player.as_mut().unwrap();
                let mut slot: usize = parts_[1].parse().unwrap();
                let stack = mk(
                    parts_[2],
                    parts_[3].parse().unwrap(),
                    parts_[4].parse().unwrap(),
                    parts_[5],
                );
                for (key, size) in &parts {
                    if slot < *size {
                        with_player_container(p, key, |c| c.set_item(slot, stack));
                        break;
                    }
                    slot -= size;
                }
                close_scene_op(&mut player, &mut menu, &sync, &mut actual);
            }
            "sync" => {
                let (p, m) = (player.as_mut().unwrap(), menu.as_mut().unwrap());
                p.take_dirty();
                m.base_mut()
                    .set_synchronizer(Box::new(Sync(sync.clone())), p);
                actual = dump(m.as_mut(), p, &sync);
            }
            "click" => {
                let (p, m) = (player.as_mut().unwrap(), menu.as_mut().unwrap());
                let clicked = m.clicked(
                    parts_[1].parse().unwrap(),
                    parts_[2].parse().unwrap(),
                    input(parts_[3]),
                    p,
                );
                if clicked.is_err() {
                    p.events.push("EXC".into());
                }
                m.broadcast_changes(p);
                actual = dump(m.as_mut(), p, &sync);
            }
            "remove" => {
                let (p, m) = (player.as_mut().unwrap(), menu.as_mut().unwrap());
                m.removed(p);
                // the generator keeps the opener hooks of its block entities silent; closing a barrel is a block
                // change (its open state), which the block goldens cover
                if p.barrel {
                    p.take_dirty();
                }
                m.broadcast_changes(p);
                actual = dump(m.as_mut(), p, &sync);
            }
            other => panic!("unknown op {other}"),
        }
    }
    finish(
        &op_line,
        &mut actual,
        &mut expected,
        &history[..history.len().saturating_sub(1)],
    );
    assert!(ops > 1500, "fixture too small: {ops} ops");
}
